def f(g):
    c=2
    rows=[i for i,r in enumerate(g) if c in r]
    out=[r[:] for r in g]
    for i in range(min(rows),max(rows)+1):
        if c not in out[i]:
            out[i]=[c+1]*len(g[0])
    return out
